const adminForm=$('adminForm'),adminInput=$('adminInput'),adminOutput=$('adminOutput');
adminForm.addEventListener('submit',e=>{e.preventDefault();const raw=adminInput.value.trim(),parts=raw.toLowerCase().split(/\s+/);adminInput.value='';if(parts[0]==='help'&&parts.length===1){adminOutput.textContent='clear: complete current room · unlock 0–4 (lobby) · level 1–18 · damage 1–1000';return}if(parts[0]==='clear'&&parts.length===1){if(!world?.started){adminOutput.textContent='Start a run first.';return}adminOutput.textContent='Sent: clear · testing runs do not earn permanent rewards.';send({type:'admin',action:'clear'});return}if(!/^(level|damage|unlock)$/.test(parts[0])||parts.length!==2||! /^(?:\d+(?:\.\d+)?|\.\d+)$/.test(parts[1])){adminOutput.textContent='Invalid command. Try help, clear, unlock 4, level 5, or damage 10.';return}const value=Number(parts[1]);if((parts[0]==='unlock'&&(!Number.isInteger(value)||value<0||value>4))||(parts[0]==='level'&&(!Number.isInteger(value)||value<1||value>18))||(parts[0]==='damage'&&(!Number.isFinite(value)||value<1||value>1000))){adminOutput.textContent='Unlock: integer 0–4. Level: integer 1–18. Damage: 1–1000.';return}if(parts[0]==='unlock'&&world?.started){adminOutput.textContent='Use unlock in the lobby before starting a run.';return}if(parts[0]!=='unlock'&&!world?.started){adminOutput.textContent='Start a run first.';return}adminOutput.textContent='Sent: '+raw+' · testing runs do not earn permanent rewards.';send({type:'admin',action:parts[0],value});});
function aimEvent(e){let r=canvas.getBoundingClientRect();aim={x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}
canvas.addEventListener('pointerdown',e=>{aimEvent(e);mouseDown=true;canvas.setPointerCapture(e.pointerId);send({type:'attack',...aim})});canvas.addEventListener('pointermove',aimEvent);canvas.addEventListener('pointerup',()=>mouseDown=false);canvas.addEventListener('pointercancel',()=>mouseDown=false);
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;let k=e.key.toLowerCase(),i=['KeyZ','KeyX','KeyC','KeyR'].indexOf(e.code);if(i>=0&&e.ctrlKey&&!e.altKey&&!e.metaKey){e.preventDefault();if(!e.repeat&&world?.started&&world.players[me]?.active)send({type:'skill_up',slot:i});return}if(e.ctrlKey||e.metaKey||e.altKey)return;if(k==='`'&&isHost){e.preventDefault();$('adminConsole').open=true;adminInput.focus();held.clear();mouseDown=false;return}if(i>=0||['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','q','f','g','v','1','2'].includes(k))e.preventDefault();if(e.repeat)return;held.add(k);if(i>=0)send({type:'cast',slot:i,...aim});if(k==='f'||k==='g'){let id=activeItems[k==='f'?0:1];if(id)send({type:'item',item:id,...aim})}if(k==='1')send({type:'item',item:'healing'});if(k==='2')send({type:'item',item:'mana_potion'});if(k==='v')send({type:'item',item:'clarity'});if(k==='q')revive()});window.addEventListener('keyup',e=>held.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{held.clear();mouseDown=false;moveTouch=null});
function revive(){let p=world?.players[me];if(!p)return;let t=Object.values(world.players).filter(x=>x.active&&x.id!==me&&x.hp<=0&&!x.revived).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(t)send({type:'revive',target:t.id});else tell('No fallen ally')}
document.querySelector('[data-action="heal"]').onclick=()=>send({type:'item',item:'healing'});document.querySelector('[data-action="mana"]').onclick=()=>send({type:'item',item:'mana_potion'});document.querySelector('[data-action="clarity"]').onclick=()=>send({type:'item',item:'clarity'});$('soundToggle').onclick=()=>{let mute=$('soundToggle').dataset.muted!=='true';$('soundToggle').dataset.muted=String(mute);$('soundToggle').textContent=mute?'Sound: off':'Sound: on';labAudio.setMuted(mute)};document.querySelector('[data-action="revive"]').onclick=revive;document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();moveTouch=b.dataset.move.split(',').map(Number);b.setPointerCapture(e.pointerId)};b.onpointerup=()=>moveTouch=null;b.onpointercancel=()=>moveTouch=null});
let finishedPersisted=null;function persistSolo(){if(!local||!world?.started||(world.gameOver&&finishedPersisted===world.runId))return;try{if(world.gameOver){settleRun();localStorage.removeItem('labyrinth-solo-v1');finishedPersisted=world.runId}else localStorage.setItem('labyrinth-solo-v1',JSON.stringify(world))}catch{tell('Unable to save on this device')}}
window.addEventListener('pagehide',persistSolo);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persistSolo()});
let tick=0,uiTime=0,saveTime=0;function frame(now){let dt=Math.min(.1,(now-last)/1000);last=now;if(world){if(local){stepLabyrinth(world,dt);saveTime+=dt;if(world.gameOver||(saveTime>=2&&world.started)){saveTime=0;persistSolo()}}tick+=dt;uiTime+=dt;if(tick>=.1){tick=0;let dx=(held.has('d')||held.has('arrowright')?1:0)-(held.has('a')||held.has('arrowleft')?1:0),dy=(held.has('s')||held.has('arrowdown')?1:0)-(held.has('w')||held.has('arrowup')?1:0);if(moveTouch)[dx,dy]=moveTouch;if(world.started&&!world.gameOver&&world.phase==='combat'){send({type:'walk',dx,dy});if(mouseDown||held.has(' '))send({type:'attack',...aim})}}observeAudio();if(uiTime>=.25){uiTime=0;ui()}draw()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
